// Prepare generation context: fetch training context once, format DNA, split into tasks
const body = $('Webhook').item.json.body || $('Webhook').item.json;
const {
  generation_run_id, personality_dna_id, audience_dna_id, product_dna_id,
  count, script_format, target_platform,
  personality_dna, audience_dna, product_dna,
  rules, content, supabase_url, supabase_service_key
} = body;

if (!content || content.length === 0) {
  return [{ json: { _no_content: true, _run_id: generation_run_id, _supabase_url: supabase_url, _supabase_key: supabase_service_key } }];
}

// Fetch training context once for the entire run
let trainingContext = '';
try {
  const tcRes = await this.helpers.httpRequest({
    method: 'POST',
    url: `${supabase_url}/functions/v1/get-training-context`,
    headers: {
      'Authorization': `Bearer ${supabase_service_key}`,
      'apikey': supabase_service_key,
      'Content-Type': 'application/json'
    },
    body: { dna_expert_id: personality_dna_id, user_id: 'default-user' },
    json: true
  });
  trainingContext = tcRes.training_context || '';
  console.log('Training context loaded:', JSON.stringify(tcRes.stats));
} catch(e) {
  console.log('Training context fetch failed (continuing without):', e.message);
}

// Format DNA as plain strings for pipeline-model-ads
const pd = personality_dna?.data || {};
const ad_dna = audience_dna?.data || {};
const prod = product_dna?.data || {};

const dnaExpert = [
  pd.about ? `Quién soy: ${pd.about}` : '',
  pd.voice ? `Mi voz y estilo: ${pd.voice}` : '',
  pd.credentials ? `Credenciales: ${pd.credentials}` : '',
  pd.forbidden_words ? `Palabras PROHIBIDAS: ${pd.forbidden_words}` : ''
].filter(Boolean).join('\n');

const dnaAudience = [
  ad_dna.ideal_client ? `Cliente ideal: ${ad_dna.ideal_client}` : '',
  ad_dna.core_belief ? `Creencia central: ${ad_dna.core_belief}` : '',
  ad_dna.testimonials ? `Prueba social: ${ad_dna.testimonials}` : '',
  ad_dna.keywords ? `Palabras que usan: ${ad_dna.keywords}` : ''
].filter(Boolean).join('\n');

const dnaProduct = [
  prod.main_problem ? `Problema que resuelvo: ${prod.main_problem}` : '',
  prod.solution_promise ? `Promesa de solución: ${prod.solution_promise}` : '',
  prod.irresistible_offer ? `Oferta: ${prod.irresistible_offer}` : '',
  prod.keywords ? `Keywords: ${prod.keywords}` : ''
].filter(Boolean).join('\n');

const maxTasks = Math.min(content.length, count || 10);
const tasks = [];

for (let i = 0; i < maxTasks; i++) {
  const piece = content[i];
  const rule = rules?.find(r => r.referente_id === piece.referente_id) || rules?.[0] || null;
  tasks.push({
    json: {
      _run_id: generation_run_id,
      _supabase_url: supabase_url,
      _supabase_key: supabase_service_key,
      _personality_dna_id: personality_dna_id,
      _audience_dna_id: audience_dna_id,
      _product_dna_id: product_dna_id,
      _rule: rule,
      _content: piece,
      _script_format: script_format || 'video_script',
      _target_platform: target_platform || 'multi',
      _dna_expert: dnaExpert,
      _dna_audience: dnaAudience,
      _dna_product: dnaProduct,
      _training_context: trainingContext,
      _no_content: false
    }
  });
}

console.log(`Created ${tasks.length} tasks with training context (${trainingContext.length} chars)`);
return tasks;

// Update generation_run as failed (no content)
const task = $input.first().json;
try {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${task._supabase_url}/rest/v1/generation_runs?id=eq.${task._run_id}`,
    headers: {
      'Authorization': `Bearer ${task._supabase_key}`,
      'apikey': task._supabase_key,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: {
      status: 'failed',
      completed_at: new Date().toISOString(),
      error_message: 'No hay contenido disponible. Agrega referentes con reglas de modelado y espera a que el banco de contenido se llene.'
    },
    json: true
  });
} catch(e) {
  console.log('Failed to update run:', e.message);
}
return [{ json: { done: true, error: 'no_content' } }];

// Parse pipeline-model-ads result and save to Supabase
const task = $('Call Pipeline').item.json;
const s = task._pipeline_result;

if (!s || !s.hook_1 || !s.cuerpo) {
  console.log('Invalid or empty pipeline response, skipping save');
  return [{ json: { ...task, _saved: false, _error: 'invalid_pipeline_response' } }];
}

const script = {
  personality_dna_id: task._personality_dna_id,
  audience_dna_id: task._audience_dna_id,
  product_dna_id: task._product_dna_id,
  source_content_id: task._content?.id || null,
  referente_id: task._content?.referente_id || null,
  referente_name: task._rule?.referentes?.name || s.referente || null,
  generation_run_id: task._run_id || null,
  hook_1: s.hook_1 || '',
  hook_2: s.hook_2 || null,
  body: s.cuerpo || '',
  cta: s.cta_1 || '',
  production_notes: s.cta_2 ? `CTA alternativo: ${s.cta_2}` : null,
  script_format: task._script_format,
  target_platform: s.platform || task._target_platform,
  what_was_modeled: s.referente || null,
  why_it_works: s.needs_review
    ? `Requiere revisión (score: ${s.quality_score}/100)`
    : `Score: ${s.quality_score}/100`,
  how_adapted: s.pending_items?.length
    ? `Pendientes: ${s.pending_items.join(', ')}`
    : null,
  status: 'draft',
  model_used: 'claude-opus-4-6'
};

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${task._supabase_url}/rest/v1/modeled_scripts`,
    headers: {
      'Authorization': `Bearer ${task._supabase_key}`,
      'apikey': task._supabase_key,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: script,
    json: true
  });
  console.log(`Saved script for: ${script.referente_name} (score: ${s.quality_score})`);
} catch(e) {
  console.log('Save script error:', e.message);
  return [{ json: { ...task, _saved: false, _error: e.message } }];
}

// Mark content as used
if (task._content?.id) {
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${task._supabase_url}/rest/v1/referente_content?id=eq.${task._content.id}`,
      headers: {
        'Authorization': `Bearer ${task._supabase_key}`,
        'apikey': task._supabase_key,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal'
      },
      body: { is_used: true },
      json: true
    });
  } catch(e) { /* ignore */ }
}

return [{ json: { ...task, _saved: true } }];

// After loop: update generation_run to completed
const allItems = $('Parse & Save').all();
const first = allItems[0]?.json || {};
const savedCount = allItems.filter(i => i.json._saved).length;

console.log(`Loop complete. Saved ${savedCount} of ${allItems.length} scripts.`);

if (first._run_id) {
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${first._supabase_url}/rest/v1/generation_runs?id=eq.${first._run_id}`,
      headers: {
        'Authorization': `Bearer ${first._supabase_key}`,
        'apikey': first._supabase_key,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal'
      },
      body: {
        status: savedCount > 0 ? 'completed' : 'failed',
        completed_at: new Date().toISOString(),
        generated_count: savedCount,
        error_message: savedCount === 0 ? 'No scripts were saved' : null
      },
      json: true
    });
    console.log(`Generation run ${first._run_id} marked as ${savedCount > 0 ? 'completed' : 'failed'}`);
  } catch(e) {
    console.log('Update run error:', e.message);
  }
}

return [{ json: { done: true, saved: savedCount, total: allItems.length } }];

// Call pipeline-model-ads for this single content piece
const task = $input.first().json;
const piece = task._content || {};
const rule = task._rule || {};

// Map referente_content fields to the Ad format expected by pipeline-model-ads
const adItem = {
  source: piece.platform || 'facebook_ads',
  link: piece.post_url || '',
  author: rule?.referentes?.name || 'Referente',
  text: (piece.original_caption || piece.transcript || '').substring(0, 3000),
  headline: piece.original_caption ? piece.original_caption.substring(0, 200) : '',
  cta: '',
  days_running: piece.days_active || null,
  views: piece.views || null,
  is_referent: true
};

console.log(`pipeline-model-ads: ${adItem.author} (${adItem.source}), text length: ${adItem.text.length}`);

let pipelineResult = null;
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `${task._supabase_url}/functions/v1/pipeline-model-ads`,
    headers: {
      'Authorization': `Bearer ${task._supabase_key}`,
      'apikey': task._supabase_key,
      'Content-Type': 'application/json'
    },
    body: {
      ads: [adItem],
      dna_expert: task._dna_expert,
      dna_audience: task._dna_audience,
      dna_product: task._dna_product,
      training_context: task._training_context || '',
      max_retries: 2,
      min_quality_score: 70
    },
    json: true,
    timeout: 180000
  });
  pipelineResult = res.scripts?.[0] || null;
  console.log(`Pipeline done: quality=${pipelineResult?.quality_score}, needs_review=${pipelineResult?.needs_review}`);
} catch(e) {
  console.log('Pipeline call failed:', e.message);
}

return [{ json: { ...task, _pipeline_result: pipelineResult } }];
